/* @define-color accent_bg_color @blue_3;
@define-color accent_fg_color white;
@define-color accent_color @blue_4; */
@define-color accent_color {{colors.primary_fixed_dim.default.hex}};
@define-color accent_fg_color {{colors.on_primary_fixed.default.hex}};
@define-color accent_bg_color {{colors.primary_fixed_dim.default.hex}};
@define-color destructive_bg_color @red_3;
@define-color destructive_fg_color white;
@define-color destructive_color @red_4;
@define-color success_bg_color @green_4;
@define-color success_fg_color white;
@define-color success_color #1b8553;
@define-color warning_bg_color @yellow_5;
@define-color warning_fg_color rgba(0,0,0,0.8);
@define-color warning_color #9c6e03;
@define-color error_bg_color @red_3;
@define-color error_fg_color white;
@define-color error_color @red_4;
/* @define-color window_bg_color #fafafb;
@define-color window_fg_color rgba(0, 0, 6, 0.8); */
@define-color window_bg_color {{colors.surface_dim.default.hex}};
@define-color window_fg_color {{colors.on_surface.default.hex}};
/* @define-color view_bg_color #ffffff;
@define-color view_fg_color rgba(0, 0, 6, 0.8); */
@define-color view_bg_color {{colors.surface.default.hex}};
@define-color view_fg_color {{colors.on_surface.default.hex}};
/* @define-color headerbar_bg_color #ebebed;
@define-color headerbar_fg_color rgba(0, 0, 6, 0.8); */
@define-color headerbar_bg_color {{colors.surface_dim.default.hex}};
@define-color headerbar_fg_color {{colors.on_surface.default.hex}};
@define-color headerbar_border_color rgba(0, 0, 6, 0.8);
@define-color headerbar_backdrop_color @window_bg_color;
@define-color headerbar_shade_color rgba(0, 0, 6, 0.12);
@define-color headerbar_darker_shade_color rgba(0, 0, 6, 0.12);
/* @define-color sidebar_bg_color #ebebed;
@define-color sidebar_fg_color rgba(0, 0, 6, 0.8);
@define-color sidebar_backdrop_color #f2f2f4; */
@define-color sidebar_shade_color rgba(0, 0, 6, 0.07);
/* @define-color sidebar_border_color rgba(0, 0, 6, 0.07); */
@define-color sidebar_bg_color @window_bg_color;
@define-color sidebar_fg_color @window_fg_color;
@define-color sidebar_border_color @window_bg_color;
@define-color sidebar_backdrop_color @window_bg_color;
/* @define-color card_bg_color #ffffff;
@define-color card_fg_color rgba(0, 0, 6, 0.8); */
@define-color card_bg_color {{colors.surface.default.hex}};
@define-color card_fg_color {{colors.on_surface.default.hex}};
@define-color card_shade_color rgba(0, 0, 6, 0.07);
@define-color dialog_bg_color #fafafb;
@define-color dialog_fg_color rgba(0, 0, 6, 0.8);
/* @define-color popover_bg_color #ffffff;
@define-color popover_fg_color rgba(0, 0, 6, 0.8); */
@define-color popover_bg_color {{colors.surface_dim.default.hex}};
@define-color popover_fg_color {{colors.on_surface.default.hex}};
@define-color popover_shade_color rgba(0, 0, 6, 0.07);
@define-color thumbnail_bg_color #ffffff;
@define-color thumbnail_fg_color rgba(0, 0, 6, 0.8);
@define-color shade_color rgba(0, 0, 6, 0.07);
@define-color scrollbar_outline_color white;
@define-color incognito_bg_color #d7e3f0;
@define-color new_title_bg_color #ffffff;

* { padding: 0; -GtkToolButton-icon-spacing: 4; -GtkTextView-error-underline-color: @error_bg_color; -GtkScrolledWindow-scrollbar-spacing: 0; -GtkToolItemGroup-expander-size: 11; -GtkWidget-text-handle-width: 20; -GtkWidget-text-handle-height: 24; -GtkDialog-button-spacing: 4; -GtkDialog-action-area-border: 0; outline-color: alpha(currentColor,0.3); outline-style: dashed; outline-offset: -3px; outline-width: 1px; -gtk-outline-radius: 7px; -gtk-secondary-caret-color: @accent_bg_color; }

