/*
 * GTK4 colors-only template (Matugen)
 *
 * Loaded as ~/.config/gtk-4.0/gtk.css at GTK_STYLE_PROVIDER_PRIORITY_USER.
 * This does NOT ship a full stylesheet — GTK4's built-in Adwaita (and
 * libadwaita) draw the widgets; we only override the named colors and
 * paint the top-level window/.background so plain GTK4 apps
 * (e.g. gtk4-widget-factory) get an opaque background instead of a
 * transparent one.
 *
 * Do not point the GTK3 adw-gtk3 stylesheet here — that is GTK3 CSS and
 * GTK4 cannot render it, which is what caused the transparent window.
 */

/* GNOME reference palette (static) — referenced by the semantic colors below */
@define-color blue_1 #99c1f1;
@define-color blue_2 #62a0ea;
@define-color blue_3 #3584e4;
@define-color blue_4 #1c71d8;
@define-color blue_5 #1a5fb4;
@define-color green_1 #8ff0a4;
@define-color green_2 #57e389;
@define-color green_3 #33d17a;
@define-color green_4 #2ec27e;
@define-color green_5 #26a269;
